	fn channel_invoke_set_volume(chan: u64, id: &u32, volume: &u8) -> Option<Result<(), Error>> {
		let mut client = Client::new(ipc_client::ChannelTransport { chan });
		client.set_volume(id, volume)
	}

	#[cfg(feature = "channel-client-impl")]
